#!/usr/bin/env python3
"""Freeze KK's GAME exemption set; no planner or input stream is modified."""
import hashlib
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
source=ROOT/'kk/data/map_weights/brc202d_tabu_locs.txt'
values=json.loads(source.read_text())
assert all(type(v) is int and 0 <= v < 481*530 for v in values)
unique=sorted(set(values));assert len(unique)==10882
sha=hashlib.sha256(source.read_bytes()).hexdigest()
header='''#pragma once
// Copyright (c) 2024 Kitty Knight. See LICENSE_KITTY_KNIGHT.
// Generated by experiments/allmaps-20260920/game-fleet/generate.py.
// Membership is the unchanged archived tabu set; duplicates collapse as in KK.
namespace cgar { namespace tricks {
inline constexpr char game_tabu_source_sha256[] = "'''+sha+'''";
inline constexpr int game_tabu_cells[] = {
'''
for start in range(0,len(unique),20):header+='    '+','.join(map(str,unique[start:start+20]))+',\n'
header+='};\n} } // namespace cgar::tricks\n'
out=ROOT/'cgar/tricks/game_fleet_tabu.hpp';out.write_text(header)
license_source=ROOT/'kk/LICENSE_PARTICIPANT'
(ROOT/'cgar/tricks/LICENSE_KITTY_KNIGHT').write_bytes(license_source.read_bytes())
proof={'source':str(source.relative_to(ROOT)),'source_sha256':sha,'source_entries':len(values),'unique_cells':len(unique),'header':str(out.relative_to(ROOT)),'header_sha256':hashlib.sha256(out.read_bytes()).hexdigest(),'membership_exact':True,'duplicate_handling':'Set membership, as in KK load_tabu_locs','reference_sources':{n:hashlib.sha256((ROOT/n).read_bytes()).hexdigest()for n in ['kk/wppl_planner/src/LaCAM2/LaCAM2Solver.cpp','kk/wppl_planner/configs/brc202d.json','kk/LICENSE_PARTICIPANT']}}
(Path(__file__).parent/'asset-proof.json').write_text(json.dumps(proof,indent=2)+'\n')
print('Generated exact KK GAME exemption membership:',len(unique))
